1	package blueprint
2	
3	import (
4		"context"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"net/http"
10		"os"
11		"path/filepath"
12		"strings"
13	)
14	
15	type CreateOptions struct {
16		Blueprint  string // required; subdirectory in the blueprints repo holding template.yaml + skeleton/
17		OutputDir  string
18		Version    string
19		SetValues  map[string]any
20		Files      []string
21		Force      bool
22		NoInput    bool
23		OutputJSON string // path to write CreateResult JSON; "-" means stdout
24		Stdin      io.Reader
25		Stdout     io.Writer
26		Stderr     io.Writer
27		HTTP       *http.Client
28		UserAgent  string
29	
30		// Test overrides. Production callers leave these zero-valued; the CLI
31		// always targets the official blueprint library at integrio-intropy/intropy-blueprints.
32		Owner         string
33		Repo          string
34		GitHubBaseURL string
35	}
36	
37	// CreateResult is the machine-readable summary written when --output-json is
38	// set. It is the contract chained scaffolder steps consume; field names are
39	// stable and additive-only.
40	type CreateResult struct {
41		Blueprint string         `json:"blueprint"`
42		Owner     string         `json:"owner"`
43		Repo      string         `json:"repo"`
44		Version   string         `json:"version"`
45		OutputDir string         `json:"outputDir"`
46		Values    map[string]any `json:"values"`
47	}
48	
49	func (o *CreateOptions) applyDefaults() {
50		if o.Owner == "" {
51			o.Owner = defaultBlueprintOwner
52		}
53		if o.Repo == "" {
54			o.Repo = defaultBlueprintRepo
55		}
56		if o.Stdin == nil {
57			o.Stdin = os.Stdin
58		}
59		if o.UserAgent == "" {
60			o.UserAgent = "intropy-cli"
61		}
62	}
63	
64	// Create runs the full scaffold: resolve release, download tarball, extract,
65	// load manifest, resolve values (with optional interactive prompting), render.
66	func Create(ctx context.Context, opts CreateOptions) error {
67		opts.applyDefaults()
68		if err := validateCreateOptions(opts); err != nil {
69			return err
70		}
71	
72		gh := newConfiguredGitHub(opts.HTTP, opts.UserAgent, opts.GitHubBaseURL)
73		tag, err := resolveReleaseTag(ctx, gh, opts.Owner, opts.Repo, opts.Version)
74		if err != nil {
75			return err
76		}
77		fmt.Fprintf(opts.Stderr, "fetching %s/%s@%s\n", opts.Owner, opts.Repo, tag)
78	
79		blueprintRoot, cleanup, err := downloadBlueprint(ctx, gh, opts.Owner, opts.Repo, tag, opts.Blueprint, "intropy-blueprint-*")
80		if err != nil {
81			return err
82		}
83		defer cleanup()
84	
85		tmpl, values, err := prepareCreateTemplate(blueprintRoot, opts)
86		if err != nil {
87			return err
88		}
89	
90		if err := renderCreateOutput(blueprintRoot, opts.Blueprint, opts.OutputDir, opts.Force, values); err != nil {
91			return err
92		}
93		fmt.Fprintf(opts.Stderr, "created %s from %s/%s@%s (blueprint %s)\n", opts.OutputDir, opts.Owner, opts.Repo, tag, opts.Blueprint)
94	
95		// The blueprint field is the repo directory name (opts.Blueprint), not
96		// tmpl.Metadata.Name — it is what a later re-fetch needs.
97		if err := WriteScaffold(opts.OutputDir, Scaffold{
98			SchemaVersion: ScaffoldSchemaVersion,
99			Blueprint:     opts.Blueprint,
100			Owner:         opts.Owner,
101			Repo:          opts.Repo,
102			Version:       tag,
103			Values:        values,
104		}); err != nil {
105			return err
106		}
107	
108		return maybeWriteCreateResult(opts, tmpl, values, tag)
109	}
110	
111	func validateCreateOptions(opts CreateOptions) error {
112		if err := validateBlueprintName(opts.Blueprint); err != nil {
113			return err
114		}
115		if opts.OutputDir == "" {
116			return errors.New("--output is required")
117		}
118		return nil
119	}
120	
121	func prepareCreateTemplate(blueprintRoot string, opts CreateOptions) (*Template, map[string]any, error) {
122		tmpl, err := LoadTemplate(filepath.Join(blueprintRoot, templateManifestName))
123		if err != nil {
124			return nil, nil, err
125		}
126	
127		prompter := selectPrompter(&opts)
128		values, err := Resolve(tmpl, opts.Files, opts.Stdin, opts.SetValues, prompter)
129		if err != nil {
130			return nil, nil, err
131		}
132		return tmpl, values, nil
133	}
134	
135	func renderCreateOutput(blueprintRoot, blueprintName, outputDir string, force bool, values map[string]any) error {
136		skelRoot := filepath.Join(blueprintRoot, blueprintSkeletonDir)
137		if info, err := os.Stat(skelRoot); err != nil || !info.IsDir() {
138			return fmt.Errorf("blueprint %q is missing %s/ directory", blueprintName, blueprintSkeletonDir)
139		}
140		if err := ensureOutputDir(outputDir, force); err != nil {
141			return err
142		}
143		return Render(skelRoot, outputDir, values)
144	}
145	
146	func maybeWriteCreateResult(opts CreateOptions, tmpl *Template, values map[string]any, tag string) error {
147		if opts.OutputJSON == "" {
148			return nil
149		}
150	
151		absOut, err := filepath.Abs(opts.OutputDir)
152		if err != nil {
153			absOut = opts.OutputDir
154		}
155		result := CreateResult{
156			Blueprint: tmpl.Metadata.Name,
157			Owner:     opts.Owner,
158			Repo:      opts.Repo,
159			Version:   tag,
160			OutputDir: absOut,
161			Values:    values,
162		}
163		if err := writeOutputJSON(opts.OutputJSON, opts.Stdout, result); err != nil {
164			return fmt.Errorf("write --output-json: %w", err)
165		}
166		return nil
167	}
168	
169	func writeOutputJSON(path string, stdout io.Writer, r CreateResult) error {
170		data, err := json.MarshalIndent(r, "", "  ")
171		if err != nil {
172			return err
173		}
174		data = append(data, '\n')
175		if path == "-" {
176			_, err := stdout.Write(data)
177			return err
178		}
179		return os.WriteFile(path, data, 0o644)
180	}
181	
182	// EnsureOutputDir creates dir if missing and refuses to render into a
183	// non-empty directory unless force is set.
184	func EnsureOutputDir(dir string, force bool) error {
185		return ensureOutputDir(dir, force)
186	}
187	
188	func ensureOutputDir(dir string, force bool) error {
189		info, err := os.Stat(dir)
190		switch {
191		case errors.Is(err, os.ErrNotExist):
192			return os.MkdirAll(dir, 0o755)
193		case err != nil:
194			return err
195		case !info.IsDir():
196			return fmt.Errorf("--output %s exists and is not a directory", dir)
197		}
198		entries, err := os.ReadDir(dir)
199		if err != nil {
200			return err
201		}
202		if len(entries) > 0 && !force {
203			return fmt.Errorf("--output %s is not empty (use --force to overwrite)", dir)
204		}
205		return nil
206	}
207	
208	// validateBlueprintName rejects empty names and anything that could escape the
209	// extracted tarball root via filepath.Join (separators, parent refs, hidden
210	// directories). The blueprint argument is user input that we turn directly into
211	// a path segment, so it has to be sanitized.
212	func validateBlueprintName(name string) error {
213		if name == "" {
214			return errors.New("blueprint name is required")
215		}
216		if name == "." || name == ".." || strings.HasPrefix(name, ".") {
217			return fmt.Errorf("invalid blueprint name %q", name)
218		}
219		if strings.ContainsAny(name, `/\`) {
220			return fmt.Errorf("invalid blueprint name %q (must be a single path segment)", name)
221		}
222		return nil
223	}
224	
225	func selectPrompter(opts *CreateOptions) Prompter {
226		return AutoPrompter(opts.Stdin, opts.Stderr, opts.NoInput)
227	}
228	
229	// AutoPrompter returns a StdinPrompter when interactive prompting is viable:
230	// noInput is false and stdin is a real terminal. In CI / piped contexts it
231	// returns nil, so Resolve reports a clean "missing required parameter(s)"
232	// error instead of hanging on a read.
233	func AutoPrompter(stdin io.Reader, out io.Writer, noInput bool) Prompter {
234		if noInput {
235			return nil
236		}
237		f, ok := stdin.(*os.File)
238		if !ok || !isTerminal(f.Fd()) {
239			return nil
240		}
241		return NewStdinPrompter(stdin, out)
242	}
