1	package blueprint
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7		"io"
8		"os"
9		"strings"
10		"text/template"
11	
12		"github.com/Masterminds/sprig/v3"
13		"github.com/santhosh-tekuri/jsonschema/v5"
14		"gopkg.in/yaml.v3"
15	)
16	
17	// StdinValuesPath is the sentinel a caller may pass in the values-file list
18	// to signal "read a single values document from this reader". It mirrors the
19	// `-f -` idiom used by helm, kubectl, and curl.
20	const StdinValuesPath = "-"
21	
22	// Resolve produces the final value map by layering, in order:
23	//
24	//	defaults declared in spec.parameters.properties[*].default
25	//	--values files (in supplied order; "-" reads one doc from stdin)
26	//	--set flags (string values, coerced to declared JSON Schema types)
27	//	prompts for required parameters still missing (when prompter != nil)
28	//
29	// stdin is consumed at most once across the files list; passing "-" twice is
30	// an error. The merged map is then validated against the JSON Schema in
31	// spec.parameters. Finally, every entry in spec.values is rendered as a Go
32	// text/template (with sprig) against the merged map and added under its key.
33	// A spec.values key that collides with a parameter name is rejected.
34	func Resolve(t *Template, files []string, stdin io.Reader, sets map[string]any, prompter Prompter) (map[string]any, error) {
35		return ResolveLayered(t, nil, files, stdin, sets, prompter)
36	}
37	
38	// ResolveLayered is Resolve with an extra base layer that sits between the
39	// spec.parameters defaults and the --values files. Callers use it to seed
40	// values from an earlier resolution (e.g. a committed scaffold record) so
41	// they take effect without re-prompting but still yield to explicit
42	// --values / --set input.
43	func ResolveLayered(t *Template, base map[string]any, files []string, stdin io.Reader, sets map[string]any, prompter Prompter) (map[string]any, error) {
44		fields := t.Fields()
45		byName := indexFields(fields)
46		out := map[string]any{}
47	
48		applyDefaultValues(fields, out)
49		for k, v := range base {
50			out[k] = coerceKnownFieldValue(k, v, byName)
51		}
52		if err := applyValuesFiles(files, stdin, out, byName); err != nil {
53			return nil, err
54		}
55		applySetValues(sets, out, byName)
56		if err := promptForMissingRequired(fields, out, prompter); err != nil {
57			return nil, err
58		}
59		if err := validateSchema(t.Spec.Parameters, out); err != nil {
60			return nil, fmt.Errorf("parameter validation: %w", err)
61		}
62		if err := renderDerivedValues(t.Spec.Values, out, byName); err != nil {
63			return nil, err
64		}
65	
66		return out, nil
67	}
68	
69	func applyDefaultValues(fields []FieldSpec, values map[string]any) {
70		for _, f := range fields {
71			if f.Default != nil {
72				values[f.Name] = f.Default
73			}
74		}
75	}
76	
77	func applyValuesFiles(files []string, stdin io.Reader, values map[string]any, byName map[string]FieldSpec) error {
78		stdinUsed := false
79		for _, path := range files {
80			if path == StdinValuesPath {
81				if stdinUsed {
82					return fmt.Errorf("--values - specified more than once (stdin can only be read once)")
83				}
84				if stdin == nil {
85					return fmt.Errorf("--values - specified but no stdin reader provided")
86				}
87				data, err := io.ReadAll(stdin)
88				if err != nil {
89					return fmt.Errorf("read values from stdin: %w", err)
90				}
91				if err := mergeValuesBytes(data, "stdin", values, byName); err != nil {
92					return err
93				}
94				stdinUsed = true
95				continue
96			}
97			if err := mergeValuesFile(path, values, byName); err != nil {
98				return err
99			}
100		}
101		return nil
102	}
103	
104	func applySetValues(sets map[string]any, values map[string]any, byName map[string]FieldSpec) {
105		for k, v := range sets {
106			values[k] = coerceKnownFieldValue(k, v, byName)
107		}
108	}
109	
110	func promptForMissingRequired(fields []FieldSpec, values map[string]any, prompter Prompter) error {
111		missing := missingRequired(fields, values)
112		if len(missing) == 0 {
113			return nil
114		}
115		if prompter == nil {
116			names := make([]string, 0, len(missing))
117			for _, f := range missing {
118				names = append(names, f.Name)
119			}
120			return fmt.Errorf("missing required parameter(s): %s", strings.Join(names, ", "))
121		}
122		for _, f := range missing {
123			ans, err := prompter.Prompt(f)
124			if err != nil {
125				return err
126			}
127			if isEmpty(ans) {
128				return fmt.Errorf("required parameter %q has no value", f.Name)
129			}
130			values[f.Name] = ans
131		}
132		return nil
133	}
134	
135	func renderDerivedValues(derived map[string]string, values map[string]any, byName map[string]FieldSpec) error {
136		for k, expr := range derived {
137			if _, collides := byName[k]; collides {
138				return fmt.Errorf("spec.values.%s collides with a parameter of the same name", k)
139			}
140			rendered, err := renderExpr(expr, values)
141			if err != nil {
142				return fmt.Errorf("spec.values.%s: %w", k, err)
143			}
144			values[k] = rendered
145		}
146		return nil
147	}
148	
149	func mergeValuesFile(path string, into map[string]any, byName map[string]FieldSpec) error {
150		data, err := os.ReadFile(path)
151		if err != nil {
152			return fmt.Errorf("read values file %s: %w", path, err)
153		}
154		return mergeValuesBytes(data, path, into, byName)
155	}
156	
157	func mergeValuesBytes(data []byte, source string, into map[string]any, byName map[string]FieldSpec) error {
158		var fileVals map[string]any
159		if err := yaml.Unmarshal(data, &fileVals); err != nil {
160			return fmt.Errorf("parse values from %s: %w", source, err)
161		}
162		for k, v := range fileVals {
163			into[k] = coerceKnownFieldValue(k, v, byName)
164		}
165		return nil
166	}
167	
168	func coerceKnownFieldValue(name string, value any, byName map[string]FieldSpec) any {
169		field, ok := byName[name]
170		if !ok {
171			return value
172		}
173		str, ok := value.(string)
174		if !ok {
175			return value
176		}
177		return coerce(str, field.Type)
178	}
179	
180	func indexFields(fields []FieldSpec) map[string]FieldSpec {
181		m := make(map[string]FieldSpec, len(fields))
182		for _, f := range fields {
183			m[f.Name] = f
184		}
185		return m
186	}
187	
188	func missingRequired(fields []FieldSpec, values map[string]any) []FieldSpec {
189		var missing []FieldSpec
190		for _, f := range fields {
191			if !f.Required {
192				continue
193			}
194			if v, ok := values[f.Name]; ok && !isEmpty(v) {
195				continue
196			}
197			missing = append(missing, f)
198		}
199		return missing
200	}
201	
202	func validateSchema(schema map[string]any, values map[string]any) error {
203		raw, err := json.Marshal(schema)
204		if err != nil {
205			return err
206		}
207		c := jsonschema.NewCompiler()
208		if err := c.AddResource("inline://params.json", bytes.NewReader(raw)); err != nil {
209			return err
210		}
211		s, err := c.Compile("inline://params.json")
212		if err != nil {
213			return err
214		}
215		return s.Validate(values)
216	}
217	
218	// renderExpr renders a Go text/template string (with sprig) against the
219	// supplied data map. Used for spec.values entries.
220	func renderExpr(expr string, data map[string]any) (string, error) {
221		tmpl, err := template.New("expr").
222			Funcs(sprig.TxtFuncMap()).
223			Option("missingkey=error").
224			Parse(expr)
225		if err != nil {
226			return "", err
227		}
228		var sb strings.Builder
229		if err := tmpl.Execute(&sb, data); err != nil {
230			return "", err
231		}
232		return sb.String(), nil
233	}
234	
235	// ParseSets converts ["key=value", ...] into a map. Values stay as strings;
236	// Resolve coerces them to the JSON Schema type when the key matches a known
237	// parameter.
238	func ParseSets(items []string) (map[string]any, error) {
239		out := map[string]any{}
240		for _, item := range items {
241			i := strings.Index(item, "=")
242			if i <= 0 {
243				return nil, fmt.Errorf("invalid --set %q (expected key=value)", item)
244			}
245			out[item[:i]] = item[i+1:]
246		}
247		return out, nil
248	}
